test('lineDiscount calculates discount correctly', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500, discountPercent: 10 }), 9500); // 950 * 0.1 = 95 euros = 9500 cents
  assert.equal(lineDiscount({ qty: 1, unitPrice: 120000, discountPercent: 10 }), 12000); // 1200 * 0.1 = 120 euros = 12000 cents
});

test('lineDiscount defaults to 0% if discountPercent not provided', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 9500 }), 0);
});

test('lineDiscount is clamped to 0', () => {
  assert.equal(lineDiscount({ qty: 10, unitPrice: 100, discountPercent: 0 }), 0);
});

test('invoiceTotals includes discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  // subtotal 95000, discount 9500, after discount 85500, VAT 21% = 17955
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455); // 95000 - 9500 + 17955
});

test('invoiceTotals with multiple lines with different discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }, // subtotal 95000, discount 9500, after 85500, VAT 17955
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 20 }, // subtotal 120000, discount 24000, after 96000, VAT 20160
    ],
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  assert.equal(totals.subtotal, 215000);
  assert.equal(totals.discount, 33500); // 9500 + 24000
  assert.equal(totals.vat, 38115); // 17955 + 20160
  assert.equal(totals.total, 219615); // 215000 - 33500 + 38115
});

test('invoiceTotals with explicit 0% discount has discount of 0 but includes VAT', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier (5%)
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }], // explicit 0% overrides tier
  });

  assert.equal(r.ok, true);
  const totals = invoiceTotals(r.value);

  // subtotal 95000, no discount, VAT 21% = 19950
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 19950);
  assert.equal(totals.total, 114950);
});

