test('lineVAT calculates VAT on line amount after discount', () => {
  // DEV-HOUR: unitPrice 9500, qty 10, no discount
  // Line total: 95000, VAT at 21%: 19950
  const line1 = { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 21 };
  assert.equal(lineVAT(line1), 19950);

  // With 10% discount: line total 85500, VAT at 21%: 17955
  const line2 = { qty: 10, unitPrice: 9500, discountPercent: 10, vatRate: 21 };
  assert.equal(lineVAT(line2), 17955);
});

test('lineVAT with 0% VAT rate returns 0', () => {
  const line = { qty: 10, unitPrice: 9500, discountPercent: 0, vatRate: 0 };
  assert.equal(lineVAT(line), 0);
});

test('lineVAT with 9% VAT rate', () => {
